create or replace function public.colearn_admin_stats() returns jsonb language plpgsql stable security definer set search_path='' as $$ begin
 if not app.staff() then raise exception 'Staff required' using errcode='42501';end if;
 return jsonb_build_object('totals',jsonb_build_object('users',(select count(*) from public.profiles),'books',(select count(*) from public.books),'projects',(select count(*) from public.projects),'threads',(select count(*) from public.threads),'reports',(select count(*) from public.reports),'skills',(select count(*) from public.skills)),
 'signups_30d',(select count(*) from public.profiles where created_at>now()-interval '30 days'),'signups_7d',(select count(*) from public.profiles where created_at>now()-interval '7 days'),'active_projects',(select count(*) from public.projects where status='active'),'books_added_30d',(select count(*) from public.books where created_at>now()-interval '30 days'),'open_reports',(select count(*) from public.reports where status in ('open','review')),'xp_awarded_30d',(select coalesce(sum(amount),0) from public.xp_events where created_at>now()-interval '30 days'),
 'daily',(select jsonb_agg(x) from(select d::date date,(select count(*) from public.profiles where created_at::date=d::date) signups,(select count(*) from public.projects where created_at::date=d::date) projects from generate_series(current_date-6,current_date,interval '1 day')d)x),'signals',jsonb_build_object('books',round(100.0*(select count(distinct user_id) from public.reading_progress where completed)/greatest((select count(*) from public.profiles),1)),'projects',round(100.0*(select count(distinct user_id) from public.project_members)/greatest((select count(*) from public.profiles),1)),'badges',round(100.0*(select count(distinct user_id) from public.user_badges)/greatest((select count(*) from public.profiles),1)),'community',round(100.0*(select count(*) from (select author_id from public.threads union select author_id from public.comments) q)/greatest((select count(*) from public.profiles),1))),'top_books',coalesce((select jsonb_agg(x) from(select b.id,b.title,b.slug,count(r.id) completions from public.books b left join public.reading_progress r on r.book_id=b.id group by b.id order by count(r.id) desc limit 5)x),'[]'));
end $$;
